// func euclideanFloat64AVX512Kernel(a uintptr, b uintptr, n int) float32
// Requires: AVX, AVX512DQ, AVX512F, FMA3, SSE
TEXT ·euclideanFloat64AVX512Kernel(SB), NOSPLIT, $0-28
	MOVQ   a+0(FP), AX
	MOVQ   b+8(FP), CX
	MOVQ   n+16(FP), DX
	VXORPD Z0, Z0, Z0

loop:
	CMPQ        DX, $0x08
	JL          tail
	VMOVUPD     (AX), Z1
	VMOVUPD     (CX), Z2
	VSUBPD      Z2, Z1, Z1
	VFMADD231PD Z1, Z1, Z0
	ADDQ        $0x40, AX
	ADDQ        $0x40, CX
	SUBQ        $0x08, DX
	JMP         loop

tail:
	VEXTRACTF64X4 $0x00, Z0, Y1
	VEXTRACTF64X4 $0x01, Z0, Y0
	VADDPD        Y1, Y0, Y0
	VEXTRACTF128  $0x00, Y0, X1
	VEXTRACTF128  $0x01, Y0, X0
	VADDPD        X1, X0, X0
	VUNPCKHPD     X0, X0, X1
	VADDSD        X1, X0, X0

scalar_loop:
	CMPQ        DX, $0x00
	JE          done
	VMOVSD      (AX), X1
	VMOVSD      (CX), X2
	VSUBSD      X2, X1, X1
	VFMADD231SD X1, X1, X0
	ADDQ        $0x08, AX
	ADDQ        $0x08, CX
	DECQ        DX
	JMP         scalar_loop

done:
	VSQRTSD   X0, X0, X0
	VCVTSD2SS X0, X0, X0
	MOVSS     X0, ret+24(FP)
	VZEROUPPER
	RET

