// func cosineFloat64AVX512Kernel(a uintptr, b uintptr, n int) (dot float32, normA float32, normB float32)
// Requires: AVX, AVX512DQ, AVX512F, FMA3, SSE
TEXT ·cosineFloat64AVX512Kernel(SB), NOSPLIT, $0-36
	MOVQ   a+0(FP), AX
	MOVQ   b+8(FP), CX
	MOVQ   n+16(FP), DX
	VXORPD Z0, Z0, Z0
	VXORPD Z1, Z1, Z1
	VXORPD Z2, Z2, Z2

loop:
	CMPQ        DX, $0x08
	JL          tail
	VMOVUPD     (AX), Z3
	VMOVUPD     (CX), Z4
	VFMADD231PD Z3, Z4, Z0
	VFMADD231PD Z3, Z3, Z1
	VFMADD231PD Z4, Z4, Z2
	ADDQ        $0x40, AX
	ADDQ        $0x40, CX
	SUBQ        $0x08, DX
	JMP         loop

tail:
	VEXTRACTF64X4 $0x00, Z0, Y3
	VEXTRACTF64X4 $0x01, Z0, Y0
	VADDPD        Y3, Y0, Y0
	VEXTRACTF128  $0x00, Y0, X3
	VEXTRACTF128  $0x01, Y0, X0
	VADDPD        X3, X0, X0
	VUNPCKHPD     X0, X0, X3
	VADDSD        X3, X0, X0
	VEXTRACTF64X4 $0x00, Z1, Y3
	VEXTRACTF64X4 $0x01, Z1, Y1
	VADDPD        Y3, Y1, Y1
	VEXTRACTF128  $0x00, Y1, X3
	VEXTRACTF128  $0x01, Y1, X1
	VADDPD        X3, X1, X1
	VUNPCKHPD     X1, X1, X3
	VADDSD        X3, X1, X1
	VEXTRACTF64X4 $0x00, Z2, Y3
	VEXTRACTF64X4 $0x01, Z2, Y2
	VADDPD        Y3, Y2, Y2
	VEXTRACTF128  $0x00, Y2, X3
	VEXTRACTF128  $0x01, Y2, X2
	VADDPD        X3, X2, X2
	VUNPCKHPD     X2, X2, X3
	VADDSD        X3, X2, X2

scalar_loop:
	CMPQ        DX, $0x00
	JE          store
	VMOVSD      (AX), X3
	VMOVSD      (CX), X4
	VFMADD231SD X3, X4, X0
	VFMADD231SD X3, X3, X1
	VFMADD231SD X4, X4, X2
	ADDQ        $0x08, AX
	ADDQ        $0x08, CX
	DECQ        DX
	JMP         scalar_loop

store:
	VCVTSD2SS X0, X0, X0
	VCVTSD2SS X1, X1, X1
	VCVTSD2SS X2, X2, X2
	MOVSS     X0, dot+24(FP)
	MOVSS     X1, normA+28(FP)
	MOVSS     X2, normB+32(FP)
	VZEROUPPER
	RET
